grid = [[4]*19 for _ in range(16)]
markers=[(2,5),(2,14),(3,1),(3,10),(5,17),(7,3),(7,13),(8,10),(10,6),(12,16),(13,10),(14,7)]
for r,c in markers: grid[r][c]=0
# Seed is already present and will be preserved.
seed=[[8,8,2],[4,9,2],[4,9,9]]
for r,c in markers:
    for dr in range(-1,2):
        for dc in range(-1,2):
            v=seed[dr+1][dc+1]
            if v != 4:
                grid[r+dr][c+dc]=v
print('\n'.join('['+', '.join(map(str,row))+'],' for row in grid))
print('dims',len(grid),set(map(len,grid)))

